"""Seam coverage for the hold-Ctrl punctuation capture (upstream #826).

``enableCtrlSymbols`` (default on, today's behaviour) gates the Ctrl+punctuation
capture: with it on, Ctrl+\\ is taken by the engine and renders the symbol from
``msymbols``; with it off the very same key event is handed back to the app
untouched, so the app's own Ctrl+\\ shortcut still fires.
"""

import os
import sys
import unittest
from unittest.mock import MagicMock

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

from test_cinbase_shift_to_english import CinbaseKeyHarness  # noqa: E402

VK_CONTROL = 0x11
VK_SHIFT = 0x10
VK_OEM_5 = 0xDC  # backslash on the US layout


class CinbaseCtrlSymbolsTests(CinbaseKeyHarness):

    @staticmethod
    def ctrl_event(char_code, key_code, control=True):
        event = MagicMock()
        event.charCode = char_code
        event.keyCode = key_code
        event.seqNum = 1
        event.repeatCount = 1
        event.scanCode = 0
        event.isExtended = False
        event.keyStates = [0] * 256
        event.isPrintableChar.return_value = True
        event.isKeyDown.side_effect = lambda vk: (
            (vk == VK_CONTROL and control) or (vk == VK_SHIFT and not control))
        event.isKeyToggled.return_value = False
        return event

    def test_ctrl_symbol_is_captured_when_enabled(self):
        service = self.activate_chesimplex()
        service.cfg.enableCtrlSymbols = True
        service.enableCtrlSymbols = True

        event = self.ctrl_event(ord("\\"), VK_OEM_5)
        claimed = service.filterKeyDown(event)
        self.assertTrue(claimed, "Ctrl+\\ should be taken by the engine")
        service.onKeyDown(event)
        self.assertEqual(service.compositionString, "＼")

    def test_ctrl_symbol_reaches_the_app_when_disabled(self):
        service = self.activate_chesimplex()
        service.cfg.enableCtrlSymbols = False
        service.enableCtrlSymbols = False
        before = dict(service.currentReply)

        event = self.ctrl_event(ord("\\"), VK_OEM_5)
        self.assertFalse(service.filterKeyDown(event),
                         "Ctrl+\\ should be handed back to the application")
        self.assertEqual(service.currentReply, before)

    def test_default_keeps_the_capture(self):
        service = self.activate_chesimplex()  # applyConfig copies the shipped value
        self.assertIs(True, service.enableCtrlSymbols,
                      "the shipped default must keep today's capture behaviour")
        self.assertIs(True, service.cfg.enableCtrlSymbols)


if __name__ == "__main__":
    unittest.main()
